    64  static void set_mem_access(MCInst *MI, bool status)
    65  {
    66          if (MI->csh->detail != CS_OPT_ON)
    67                  return;
    68
    69          MI->csh->doing_mem = status;
    70          if (!status)
    71                  // done, create the next operand slot
    72                  MI->flat_insn->detail->x86.op_count++;
    73
    74  }
