    76  static void printopaquemem(MCInst *MI, unsigned OpNo, SStream *O)
    77  {
    78          // FIXME: do this with autogen
    79          // printf(">>> ID = %u\n", MI->flat_insn->id);
    80          switch(MI->flat_insn->id) {
    81                  default:
    82                          SStream_concat0(O, "ptr ");
    83                          break;
    84                  case X86_INS_SGDT:
    85                  case X86_INS_SIDT:
    86                  case X86_INS_LGDT:
    87                  case X86_INS_LIDT:
    88                  case X86_INS_FXRSTOR:
    89                  case X86_INS_FXSAVE:
    90                  case X86_INS_LJMP:
    91                  case X86_INS_LCALL:
    92                          // do not print "ptr"
    93                          break;
    94          }
    95
    96          switch(MI->csh->mode) {
    97                  case CS_MODE_16:
    98                          switch(MI->flat_insn->id) {
    99                                  default:
   100                                          MI->x86opsize = 2;
   101                                          break;
   102                                  case X86_INS_LJMP:
   103                                  case X86_INS_LCALL:
   104                                          MI->x86opsize = 4;
   105                                          break;
   106                                  case X86_INS_SGDT:
   107                                  case X86_INS_SIDT:
   108                                  case X86_INS_LGDT:
   109                                  case X86_INS_LIDT:
   110                                          MI->x86opsize = 6;
   111                                          break;
   112                          }
   113                          break;
   114                  case CS_MODE_32:
   115                          switch(MI->flat_insn->id) {
   116                                  default:
   117                                          MI->x86opsize = 4;
   118                                          break;
   119                                  case X86_INS_LJMP:
   120                                  case X86_INS_JMP:
   121                                  case X86_INS_LCALL:
   122                                  case X86_INS_SGDT:
   123                                  case X86_INS_SIDT:
   124                                  case X86_INS_LGDT:
   125                                  case X86_INS_LIDT:
   126                                          MI->x86opsize = 6;
   127                                          break;
   128                          }
   129                          break;
   130                  case CS_MODE_64:
   131                          switch(MI->flat_insn->id) {
   132                                  default:
   133                                          MI->x86opsize = 8;
   134                                          break;
   135                                  case X86_INS_LJMP:
   136                                  case X86_INS_LCALL:
   137                                  case X86_INS_SGDT:
   138                                  case X86_INS_SIDT:
   139                                  case X86_INS_LGDT:
   140                                  case X86_INS_LIDT:
   141                                          MI->x86opsize = 10;
   142                                          break;
   143                          }
   144                          break;
   145                  default:        // never reach
   146                          break;
   147          }
   148
   149          printMemReference(MI, OpNo, O);
   150  }
