   524  /// printPCRelImm - This is used to print an immediate value that ends up
   525  /// being encoded as a pc-relative value (e.g. for jumps and calls).  These
   526  /// print slightly differently than normal immediates.  For example, a $ is not
   527  /// emitted.
   528  static void printPCRelImm(MCInst *MI, unsigned OpNo, SStream *O)
   529  {
   530          MCOperand *Op = MCInst_getOperand(MI, OpNo);
   531          if (MCOperand_isImm(Op)) {
   532                  int64_t imm = MCOperand_getImm(Op) + MI->flat_insn->size + MI->address;
   533
   534                  // truncat imm for non-64bit
   535                  if (MI->csh->mode != CS_MODE_64) {
   536                          imm = imm & 0xffffffff;
   537                  }
   538
   539                  if (imm < 0) {
   540                          SStream_concat(O, "0x%"PRIx64, imm);
   541                  } else {
   542                          if (imm > HEX_THRESHOLD)
   543                                  SStream_concat(O, "0x%"PRIx64, imm);
   544                          else
   545                                  SStream_concat(O, "%"PRIu64, imm);
   546                  }
   547                  if (MI->csh->detail) {
   548                          MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_IMM;
   549                          MI->has_imm = true;
   550                          MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].imm = imm;
   551                          MI->flat_insn->detail->x86.op_count++;
   552                  }
   553          }
   554  }
