   556  static void printOperand(MCInst *MI, unsigned OpNo, SStream *O)
   557  {
   558          MCOperand *Op  = MCInst_getOperand(MI, OpNo);
   559          if (MCOperand_isReg(Op)) {
   560                  unsigned int reg = MCOperand_getReg(Op);
   561                  printRegName(O, reg);
   562                  if (MI->csh->detail) {
   563                          if (MI->csh->doing_mem) {
   564                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.base = X86_register_map(reg);
   565                          } else {
   566                                  uint8_t access[6];
   567
   568                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_REG;
   569                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].reg = X86_register_map(reg);
   570                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->csh->regsize_map[X86_register_map(reg)];
   571
   572                                  get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
   573                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
   574
   575                                  MI->flat_insn->detail->x86.op_count++;
   576                          }
   577                  }
   578          } else if (MCOperand_isImm(Op)) {
   579                  // Print X86 immediates as signed values.
   580                  uint8_t encsize;
   581                  int64_t imm = MCOperand_getImm(Op);
   582                  uint8_t opsize = X86_immediate_size(MCInst_getOpcode(MI), &encsize);
   583
   584                  if (opsize == 1)    // print 1 byte immediate in positive form
   585                          imm = imm & 0xff;
   586
   587                  switch(MI->flat_insn->id) {
   588                          default:
   589                                  if (imm >= 0) {
   590                                          if (imm > HEX_THRESHOLD)
   591                                                  SStream_concat(O, "$0x%"PRIx64, imm);
   592                                          else
   593                                                  SStream_concat(O, "$%"PRIu64, imm);
   594                                  } else {
   595                                          if (MI->csh->imm_unsigned) {
   596                                                  if (opsize) {
   597                                                        switch(opsize) {
   598                                                          default:
   599                                                                  break;
   600                                                          case 1:
   601                                                                  imm &= 0xff;
   602                                                                  break;
   603                                                          case 2:
   604                                                                  imm &= 0xffff;
   605                                                                  break;
   606                                                          case 4:
   607                                                                  imm &= 0xffffffff;
   608                                                                  break;
   609                                                        }
   610                                                  }
